def clean(df):
    df['Quantity'] = df['Quantity'].astype(int).clip(0, 8)
    df['Region'] = df['Region'].str.strip().str.title()
    allowed_regions = ['North', 'South', 'East', 'West']
    df['Region'] = df['Region'].apply(lambda x: x if x in allowed_regions else pd.NA)
    return df

def answer(df):
    grouped = df.groupby('Region')['Quantity'].sum().reset_index()
    result = grouped[grouped['Region'].notna()]
    return {row['Region']: row['Quantity'] for row in result}
